// src/screens/SettingsScreen.js - экран настроек приложения

// ... (импорты и другой код)
// Предполагая, что здесь импортирован useStorage для сброса данных:
// import useStorage from '../hooks/useStorage';

const SettingsScreen = () => {
  // ... (состояние settings)

  // ... (toggleSetting, copyAppInfo)

  // ❗ ИЗМЕНЕНИЕ ФУНКЦИИ СБРОСА ДАННЫХ
  const resetData = () => {
    Alert.alert(
      'Сброс данных',
      'Вы уверены, что хотите сбросить все данные приложения? Это действие нельзя отменить.',
      [
        { text: 'Отмена', style: 'cancel' },
        { 
          text: 'Сбросить', 
          style: 'destructive',
          onPress: () => {
            // ❌ УДАЛИТЬ: Вызов clearData() для ключа 'counter'
            // Например, если раньше было:
            // clearCounterData();
            // clearGalleryData();

            // Теперь нужно оставить только вызовы для НЕ-счетчика:
            // Предположим, что вы вызываете функцию очистки галереи:
            // clearGalleryData(); 

            Alert.alert('Успех', 'Данные приложения (кроме счетчика) были сброшены');
          }
        },
      ]
    );
  };

  // ... (остальной код компонента)

  return (
    <ScrollView style={styles.container}>
      {/* ... (Настройки) */}

      <View style={styles.actionsRow}>
        {/* ... (copyAppInfo) */}

        {/* ❗ КНОПКА СБРОСА */}
        <TouchableOpacity 
          style={[styles.actionButton, { backgroundColor: '#FF3B3010' }]} 
          onPress={resetData}
        >
          <Ionicons name="trash-outline" size={20} color="#FF3B30" />
          <Text style={[styles.actionButtonText, { color: '#FF3B30' }]}>Сбросить все данные</Text>
        </TouchableOpacity>
      </View>
    </ScrollView>
  );
};

export default SettingsScreen;
// ... (стили)
